uint32_t getleft(uint64_t x){return (x>>32)&0xFFFFFFFF;}
uint32_t getright(uint64_t x){return x&0xFFFFFFFF;}

#define PCONST 12345

// truncated expand: s_low is k-bit value, returns low k bits of expand(s) (for any s extending s_low)
uint32_t expand_trunc(uint32_t s_low, int k){
    if(k==0) return 0;
    uint64_t mask = (k>=32)?0xFFFFFFFFULL:((1ULL<<k)-1);
    uint64_t s = s_low & mask;
    uint64_t t1 = s;
    uint64_t t2 = (s<<16) & mask; // low k bits of s<<16: only depends on low k bits
    uint64_t t3 = (s * PCONST) & mask;
    return (uint32_t)((t1 ^ t2 ^ t3) & mask);
}
uint32_t expand_full(uint32_t s){
    return s ^ (s<<16) ^ (s*PCONST);
}

