// check partial assignment with k bits known (k = number of seed bits known, 0..20). s_low[4] are k-bit values.
// Returns 1 if no contradiction (keep), 0 if prune.
int check_partial(uint32_t s_low[4], int k){
    // compute K known flags/values (32 bits each)
    int kK[4][32]; uint8_t vK[4][32];
    for(int r=0;r<4;r++){
        uint32_t Klow = expand_trunc(s_low[r], k);
        for(int j=0;j<32;j++){
            if(j<k){ kK[r][j]=1; vK[r][j]=(Klow>>j)&1; }
            else { kK[r][j]=0; vK[r][j]=0; }
        }
    }
    // for each pair, simulate
    for(int pi=0; pi<nPairs; pi++){
        uint32_t PL = getleft(P[pi]);
        uint32_t PR = getright(P[pi]);
        uint32_t CH = getleft(C[pi]); // note merge(right,left): high=right=R4, low=left=L4^R4
        uint32_t CL = getright(C[pi]);
        // Actually C high = R4, C low = L4^R4. So R4=CH, L4=CL^CH.
        // But for forward check, we simulate forward and compare to CH,CL.
        // L0,R0 known
        int kL[32], kR[32]; uint8_t vL[32], vR[32];
        // L0 = PL, R0 = PR ^ PL
        for(int j=0;j<32;j++){
            int pl = (PL>>j)&1, pr=(PR>>j)&1;
            kL[j]=1; vL[j]=pl;
            kR[j]=1; vR[j]=(pr^pl)&1;
        }
        int curkL[32], curkR[32]; uint8_t curvL[32], curvR[32];
        memcpy(curkL,kL,sizeof(kL)); memcpy(curkR,kR,sizeof(kR)); memcpy(curvL,vL,sizeof(vL)); memcpy(curvR,vR,sizeof(vR));
        for(int round=0;round<4;round++){
            // T = curR xor K
            int kT[32]; uint8_t vT[32];
            for(int j=0;j<32;j++){
                kT[j]=curkR[j] && kK[round][j];
                vT[j]=(curvR[j]^vK[round][j])&1;
            }
            int kF[32]; uint8_t vF[32];
            F_tv(kT,vT,kF,vF);
            // Rnext = curL xor F, Lnext = curR
            int nkL[32], nkR[32]; uint8_t nvL[32], nvR[32];
            for(int j=0;j<32;j++){
                nkL[j]=curkR[j]; nvL[j]=curvR[j];
                nkR[j]=curkL[j] && kF[j]; nvR[j]=(curvL[j]^vF[j])&1;
            }
            memcpy(curkL,nkL,sizeof(nkL)); memcpy(curkR,nkR,sizeof(nkR)); memcpy(curvL,nvL,sizeof(nvL)); memcpy(curvR,nvR,sizeof(nvR));
        }
        // post: L4 ^= R4 : Lpost = L4 xor R4, Rpost=R4
        int kLp[32], kRp[32]; uint8_t vLp[32], vRp[32];
        for(int j=0;j<32;j++){
            kRp[j]=curkR[j]; vRp[j]=curvR[j];
            kLp[j]=curkL[j] && curkR[j]; vLp[j]=(curvL[j]^curvR[j])&1;
        }
        // cipher high = Rpost, low = Lpost
        for(int j=0;j<32;j++){
            int ch = (CH>>j)&1, cl=(CL>>j)&1;
            if(kRp[j] && (vRp[j]!=ch)) return 0;
            if(kLp[j] && (vLp[j]!=cl)) return 0;
        }
    }
    return 1;
}

long long nodes=0, pruned=0;
uint32_t solution[4]; int found=0;

void dfs(int k, uint32_t s_low[4]){
    if(found) return;
    if(k==20){
        // full check exact
        uint32_t K[4];
        for(int r=0;r<4;r++) K[r]=expand_full(s_low[r]&0xFFFFF);
        for(int pi=0;pi<nPairs;pi++){
            uint32_t left=getleft(P[pi]), right=getright(P[pi]);
            right ^= left;
            for(int rn=0;rn<4;rn++){
                // f
                uint32_t inp = right ^ K[rn];
                // compute f exactly
                uint8_t x[4], y[4];
                uint32_t t=inp;
                for(int i=0;i<4;i++){ x[i]=t&0xFF; t>>=8; }
                // g
                #define G(a,b,xc) (uint8_t)(((((a)+(b)+(xc))&0xFF)<<2 | ((((a)+(b)+(xc))&0xFF)>>6))&0xFF)
                y[2]=G(x[3]^x[2],x[1]^x[0],1);
                y[3]=G(x[3],y[2],0);
                y[1]=G(x[1]^x[0],y[2],0);
                y[0]=G(x[0],y[1],1);
                uint32_t out=0;
                for(int i=0;i<4;i++) out|=(uint32_t)y[i]<<(8*i);
                uint32_t tmp=right; right=left^out; left=tmp;
            }
            left ^= right;
            uint64_t ct = ((uint64_t)right<<32)|(left&0xFFFFFFFF);
            // note merge(right,left): high=right,low=left
            if(ct!=C[pi]) return;
        }
        printf("FOUND seeds: %05x %05x %05x %05x\n", s_low[0],s_low[1],s_low[2],s_low[3]);
        for(int r=0;r<4;r++) solution[r]=s_low[r];
        found=1;
        return;
    }
    // branch 16 combos for bit k
    for(int mask=0;mask<16;mask++){
        if(found) return;
        uint32_t ns[4];
        for(int r=0;r<4;r++) ns[r]=s_low[r] | (((mask>>r)&1)<<k);
        nodes++;
        if(!check_partial(ns,k+1)){ pruned++; continue; }
        dfs(k+1, ns);
    }
}

int main(){
    FILE *fp=fopen("/app/pairs.txt","r");
    if(!fp){perror("pairs");return 1;}
    char line[256];
    while(fgets(line,sizeof(line),fp)){
        unsigned long long a,b;
        if(sscanf(line,"%llu %llu",&a,&b)==2){ P[nPairs]=(uint64_t)a; C[nPairs]=(uint64_t)b; nPairs++; }
    }
    fclose(fp);
    printf("loaded %d pairs\n",nPairs);
    // quick sanity: check_partial with k=0 should pass (no info)
    uint32_t s0[4]={0,0,0,0};
    printf("check k=0: %d\n", check_partial(s0,0));
    dfs(0,s0);
    printf("nodes=%lld pruned=%lld found=%d\n",nodes,pruned,found);
    if(found){
        printf("%05x %05x %05x %05x\n",solution[0],solution[1],solution[2],solution[3]);
        FILE *out=fopen("/tmp/keys.txt","w");
        fprintf(out,"%05x %05x %05x %05x\n",solution[0],solution[1],solution[2],solution[3]);
        fclose(out);
    }
    return 0;
}
